contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _owner) public payable {
        address originalOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool adminReverted;
        bool adminReturned;

        bool success = c.setOwner(_owner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            adminReverted = true;
        } else {
            adminReturned = success;
            adminReverted = false;
        }

        assert(adminReverted ? c.owner() == originalOwner : (adminReturned && c.owner() == _owner));
    }
}

