contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address _owner) internal {
        address originalOwner;
        try c.owner() returns (address __r) { originalOwner = __r; } catch { return; }
        bool adminReverted;
        bool adminReturned;
        try c.setOwner(_owner) returns (bool success) {
            adminReturned = success;
            adminReverted = false;
        } catch {
            adminReverted = true;
        }
